"""
PDF report writer
-----------------
Renders the console report into a PDF without any third-party library:
a monospaced Type1 base font (Courier) plus a hand-built PDF object table,
so the ASCII kundli and the Varga grid keep their alignment.
"""

# Generated by GitHub Copilot - Sep-27-2026

from __future__ import annotations

import datetime
import io

# Page sizes in PostScript points (1/72 inch).
PAGE_SIZES = {
    "a4": (595.28, 841.89),
    "letter": (612.0, 792.0),
}

# Courier advance width is 0.6 em for every glyph.
_CHAR_WIDTH_RATIO = 0.6

# Box-drawing and symbols that WinAnsiEncoding cannot show, mapped to plain text.
_TRANSLITERATE = {
    "═": "=", "─": "-", "━": "-", "│": "|", "┃": "|",
    "┌": "+", "┐": "+", "└": "+", "┘": "+",
    "├": "+", "┤": "+", "┬": "+", "┴": "+", "┼": "+",
    "╔": "+", "╗": "+", "╚": "+", "╝": "+",
    "℞": "(R)", "◆": "*", "⚠": "!", "✗": "x", "✓": "v", "→": "->",
    "🙏": "", "’": "'", "‘": "'", "“": '"', "”": '"', "…": "...",
    "Δ": "Delta ", "λ": "lambda", "β": "beta", "°": "\u00b0",
}


class Tee:
    """Write to several streams at once, so the console output can be captured."""

    def __init__(self, *streams):
        self.streams = streams

    def write(self, data: str) -> int:
        for stream in self.streams:
            stream.write(data)
        return len(data)

    def flush(self):
        for stream in self.streams:
            stream.flush()


def _to_winansi(text: str) -> str:
    """Make a line printable with the WinAnsi-encoded base font."""
    for src, dst in _TRANSLITERATE.items():
        text = text.replace(src, dst)
    return text.encode("cp1252", "replace").decode("cp1252")


def _escape(text: str) -> str:
    return text.replace("\\", r"\\").replace("(", r"\(").replace(")", r"\)")


def _paginate(lines: list[str], rows_per_page: int) -> list[list[str]]:
    pages: list[list[str]] = []
    for start in range(0, len(lines), rows_per_page):
        pages.append(lines[start:start + rows_per_page])
    return pages or [[]]


def text_to_pdf(text: str, path: str, title: str = "Jyotish Report",
                author: str = "Jyotish Calculator", page_size: str = "a4",
                landscape: bool = False, font_size: float = 9.0,
                margin: float = 28.0) -> str:
    """
    Write monospaced report text to `path` as a PDF. The font size is reduced
    automatically if a line is too wide to fit, so tables never wrap.
    """
    width, height = PAGE_SIZES.get(page_size.lower(), PAGE_SIZES["a4"])
    if landscape:
        width, height = height, width

    lines = [_to_winansi(line.rstrip("\n")) for line in text.splitlines()]
    usable_width = width - 2 * margin
    longest = max((len(line) for line in lines), default = 1) or 1
    max_size = usable_width / (longest * _CHAR_WIDTH_RATIO)
    font_size = max(4.5, min(font_size, max_size))

    leading = font_size * 1.22
    rows_per_page = max(1, int((height - 2 * margin - leading) / leading))
    pages = _paginate(lines, rows_per_page)

    objects: list[bytes] = []          # object number n is objects[n-1]

    def add(obj: bytes) -> int:
        objects.append(obj)
        return len(objects)

    catalog_num = add(b"")             # reserved, filled in below
    pages_num = add(b"")
    font_num = add(b"<< /Type /Font /Subtype /Type1 /BaseFont /Courier "
                   b"/Encoding /WinAnsiEncoding >>")

    page_nums: list[int] = []
    for index, page_lines in enumerate(pages, start=1):
        stream = io.StringIO()
        stream.write("BT\n")
        stream.write(f"/F1 {font_size:.2f} Tf\n")
        stream.write(f"{leading:.2f} TL\n")
        stream.write(f"1 0 0 1 {margin:.2f} {height - margin - font_size:.2f} Tm\n")
        for line in page_lines:
            stream.write(f"({_escape(line)}) Tj T*\n")
        footer = f"{title}  -  page {index} of {len(pages)}"
        stream.write(f"1 0 0 1 {margin:.2f} {margin / 2:.2f} Tm\n")
        stream.write(f"({_escape(footer)}) Tj\n")
        stream.write("ET\n")
        content = stream.getvalue().encode("cp1252", "replace")

        content_num = add(b"<< /Length " + str(len(content)).encode() + b" >>\nstream\n"
                          + content + b"\nendstream")
        page_num = add(
            b"<< /Type /Page /Parent " + str(pages_num).encode() + b" 0 R "
            b"/MediaBox [0 0 " + f"{width:.2f} {height:.2f}".encode() + b"] "
            b"/Resources << /Font << /F1 " + str(font_num).encode() + b" 0 R >> >> "
            b"/Contents " + str(content_num).encode() + b" 0 R >>")
        page_nums.append(page_num)

    kids = b" ".join(f"{n} 0 R".encode() for n in page_nums)
    objects[pages_num - 1] = (b"<< /Type /Pages /Kids [" + kids + b"] /Count "
                              + str(len(page_nums)).encode() + b" >>")
    objects[catalog_num - 1] = (b"<< /Type /Catalog /Pages "
                                + str(pages_num).encode() + b" 0 R >>")

    stamp = datetime.datetime.now().strftime("D:%Y%m%d%H%M%S")
    info_num = add(b"<< /Title (" + _escape(title).encode("cp1252", "replace")
                   + b") /Author (" + _escape(author).encode("cp1252", "replace")
                   + b") /Producer (Jyotish Calculator) /CreationDate ("
                   + stamp.encode() + b") >>")

    out = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0]
    for number, body in enumerate(objects, start=1):
        offsets.append(len(out))
        out += f"{number} 0 obj\n".encode() + body + b"\nendobj\n"

    xref_pos = len(out)
    count = len(objects) + 1
    out += f"xref\n0 {count}\n".encode()
    out += b"0000000000 65535 f \n"
    for offset in offsets[1:]:
        out += f"{offset:010d} 00000 n \n".encode()
    out += (b"trailer\n<< /Size " + str(count).encode()
            + b" /Root " + str(catalog_num).encode() + b" 0 R"
            + b" /Info " + str(info_num).encode() + b" 0 R >>\n"
            + b"startxref\n" + str(xref_pos).encode() + b"\n%%EOF\n")

    with open(path, "wb") as fh:
        fh.write(out)
    return path
